from typing import List


class Solution:
    def minOperations(self, nums: List[int]) -> int:
        limit = max(nums) + 1
        spf = list(range(limit))
        p = 2
        while p * p < limit:
            if spf[p] == p:
                for m in range(p * p, limit, p):
                    if spf[m] == m:
                        spf[m] = p
            p += 1
        ops = 0
        for i in range(len(nums) - 2, -1, -1):
            if nums[i] > nums[i + 1]:
                reduced = spf[nums[i]]
                if reduced == nums[i] or reduced > nums[i + 1]:
                    return -1
                nums[i] = reduced
                ops += 1
        return ops

